import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

// Set Mapbox access token
mapboxgl.accessToken = 'pk.eyJ1IjoiYXZlcnljb3RlIiwiYSI6ImNtZWxpdmpxMzBpOWQyanE0Z2p2YWRicjIifQ.fQzZ_KDIxILvcV471Z3EjQ';

const SimpleMapTest = () => {
  const mapContainer = useRef(null);
  const map = useRef(null);
  const [status, setStatus] = useState('Initializing...');
  const [error, setError] = useState(null);

  useEffect(() => {
    if (map.current) return;

    const initializeMap = async () => {
      try {
        setStatus('Creating map instance...');
        console.log('SimpleMapTest: Starting map initialization');
        
        // Test if Mapbox is available
        if (!mapboxgl) {
          throw new Error('Mapbox GL JS is not loaded');
        }

        // Test access token
        if (!mapboxgl.accessToken) {
          throw new Error('Mapbox access token is not set');
        }

        setStatus('Loading map tiles...');
        
        map.current = new mapboxgl.Map({
          container: mapContainer.current,
          style: 'mapbox://styles/mapbox/streets-v12',
          center: [-63.5756, 44.6475], // Halifax
          zoom: 12,
          // Minimal configuration for testing
          preserveDrawingBuffer: false,
          antialias: false,
          attributionControl: false
        });

        map.current.on('load', () => {
          setStatus('Map loaded successfully!');
          console.log('SimpleMapTest: Map loaded successfully');
        });

        map.current.on('error', (e) => {
          console.error('SimpleMapTest: Map error:', e);
          setError(`Map error: ${e.error?.message || 'Unknown error'}`);
          setStatus('Map failed to load');
        });

        map.current.on('styledata', () => {
          console.log('SimpleMapTest: Map style loaded');
        });

        map.current.on('sourcedata', (e) => {
          console.log('SimpleMapTest: Source data event:', e);
        });

      } catch (err) {
        console.error('SimpleMapTest: Failed to initialize map:', err);
        setError(`Initialization error: ${err.message}`);
        setStatus('Failed to initialize');
      }
    };

    initializeMap();

    return () => {
      if (map.current) {
        map.current.remove();
        map.current = null;
      }
    };
  }, []);

  return (
    <div style={{ 
      position: 'relative', 
      width: '100%', 
      height: '100vh',
      border: '2px solid #ccc'
    }}>
      <div 
        ref={mapContainer} 
        style={{ 
          width: '100%', 
          height: '100%' 
        }} 
      />
      
      {/* Status overlay */}
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '10px',
        background: 'rgba(0, 0, 0, 0.8)',
        color: 'white',
        padding: '10px',
        borderRadius: '5px',
        fontFamily: 'monospace',
        fontSize: '14px',
        zIndex: 1000
      }}>
        <div><strong>Status:</strong> {status}</div>
        {error && (
          <div style={{ color: '#ff6b6b', marginTop: '5px' }}>
            <strong>Error:</strong> {error}
          </div>
        )}
        <div style={{ marginTop: '5px', fontSize: '12px' }}>
          <div>Mapbox Token: {mapboxgl.accessToken ? '✅ Set' : '❌ Missing'}</div>
          <div>Map Instance: {map.current ? '✅ Created' : '❌ Not created'}</div>
        </div>
      </div>

      {/* Test controls */}
      <div style={{
        position: 'absolute',
        top: '10px',
        right: '10px',
        background: 'rgba(0, 0, 0, 0.8)',
        color: 'white',
        padding: '10px',
        borderRadius: '5px',
        zIndex: 1000
      }}>
        <button 
          onClick={() => window.location.reload()}
          style={{
            background: '#3498db',
            color: 'white',
            border: 'none',
            padding: '5px 10px',
            borderRadius: '3px',
            cursor: 'pointer',
            marginRight: '5px'
          }}
        >
          Reload
        </button>
        <button 
          onClick={() => {
            if (map.current) {
              console.log('Map instance:', map.current);
              console.log('Map style:', map.current.getStyle());
              console.log('Map loaded:', map.current.isStyleLoaded());
            }
          }}
          style={{
            background: '#e74c3c',
            color: 'white',
            border: 'none',
            padding: '5px 10px',
            borderRadius: '3px',
            cursor: 'pointer'
          }}
        >
          Debug
        </button>
      </div>
    </div>
  );
};

export default SimpleMapTest;
